<?php require '_top.php';$map=['equipe'=>['nome','funcao','responsabilidade','email'],'estrategias'=>['titulo','descricao','categoria','ordem','ativo'],'kpis'=>['nome','valor','unidade','descricao'],'timeline'=>['data','titulo','descricao','ordem'],'conteudos'=>['titulo','conteudo','secao']];$table=$_GET['t']??'';if(!isset($map[$table]))exit('Recurso inválido');$fields=$map[$table];if(isset($_GET['delete'])){$s=db()->prepare("DELETE FROM `$table` WHERE id=?");$s->execute([(int)$_GET['delete']]);header("Location: crud.php?t=$table");exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$vals=[];foreach($fields as $f)$vals[]=$_POST[$f]??'';if(!empty($_POST['id'])){$set=implode(',',array_map(fn($f)=>"`$f`=?",$fields));$vals[]=(int)$_POST['id'];db()->prepare("UPDATE `$table` SET $set WHERE id=?")->execute($vals);}else{db()->prepare("INSERT INTO `$table` (`".implode('`,`',$fields).'`) VALUES ('.implode(',',array_fill(0,count($fields),'?')).')')->execute($vals);}header("Location: crud.php?t=$table");exit;}$edit=isset($_GET['edit'])?one($table,(int)$_GET['edit']):[];?><p><a href="<?=e($table)?>.php">← voltar</a></p><h1><?=ucfirst($table)?></h1><form class="contact" method="post"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><?php foreach($fields as $f):$v=$edit[$f]??'';if(in_array($f,['descricao','conteudo','responsabilidade'])): ?><textarea name="<?=e($f)?>" placeholder="<?=e($f)?>"><?=e($v)?></textarea><?php else:?><input <?= $f==='data'?'type="date"':'' ?> name="<?=e($f)?>" value="<?=e($v)?>" placeholder="<?=e($f)?>"><?php endif;endforeach?><button class="button">Salvar</button></form><div class="cards grid"><?php foreach(rows($table, $table==='timeline'?'ordem':'id') as $x):?><article><h3><?=e($x[$fields[0]])?></h3><p><?=e($x[$fields[1]]??'')?></p><a href="?t=<?=$table?>&edit=<?=$x['id']?>">Editar</a> · <a onclick="return confirm('Excluir este item?')" href="?t=<?=$table?>&delete=<?=$x['id']?>">Excluir</a></article><?php endforeach?></div><?php require '_bottom.php'; ?>
